     // 16x16 piece of A","    wmma::load_matrix_sync(b, B + k * N + tileCol, N);        // 16x16 piece of B","    wmma::mma_sync(acc, a, b, acc);                           // acc += a x b on tensor cores","  }","  wmma::store_matrix_sync(C + tileRow * N + tileCol, acc, N, wmma::mem_row_major);","}"],"note":"Each 16 x 16 x 16 <code>mma_sync</code> becomes two <code>HMMA.16816</code> (two 16 x 8 halves of the output); the loop is unrolled, so 10 HMMA appear on sm_90a. The same HMMA on all four targets: WMMA is the portable path, but on sm_90a it cannot reach the Hopper-only wgmma instruction."},{"id":"k7_mma_fp8","title":"7. One FP8 mma.sync (inline PTX)","block":32,"about":"A single warp-wide m16n8k32 FP8 (e4m3) tensor-core instruction written directly in PTX. Compiled, not run.","arch":{"sm_80":{"ok":false,"err":"ptxas k7_mma_fp8.ptx, line 57; error   : Feature 'mma with FP8 floating point type' requires .target sm_89 or higher\nptxas fatal   : Ptx assembly aborted due to errors","errShort":"Feature 'mma with FP8 floating point type' requires .target sm_89 or higher"},"sm_90a":{"ok":true,"res":{"regs":20,"smem":0,"spillSt":0,"spillLd":0,"stack":0,"bars":0},"tc":"HMMA.16816.F32","sass":["LDC R1, c[0x0][0x28]\nS2R R0, SR_TID.X\nLDC.64 R8, c[0x0][0x218]\nULDC.64 UR4, c[0x0][0x208]\nLDC.64 R2, c[0x0][0x210]\nIMAD.SHL.U32 R4, R0.reuse, 0x2, RZ\nIMAD.SHL.U32 R0, R0, 0x4, RZ\nLOP3.LUT R5, R4, 0x3e, RZ, 0xc0, !PT\nLOP3.LUT R0, R0, 0x7c, RZ, 0xc0, !PT\nIMAD.WIDE.U32 R8, R5, 0x4, R8\nIMAD.WIDE.U32 R2, R0.reuse, 0x4, R2\nLDG.E R14, desc[UR4][R8.64]\nLDG.E R15, desc[UR4][R8.64+0x4]\nLDG.E R10, desc[UR4][R2.64]\nLDG.E R11, desc[UR4][R2.64+0x4]\nLDG.E R12, desc[UR4][R2.64+0x8]\nLDG.E R13, desc[UR4][R2.64+0xc]\nLDC.64 R2, c[0x0][0x220]\nIMAD.WIDE.U32 R2, R0, 0x4, R2\nF2FP.F16.E4M3.UNPACK_B R16, R14\nF2FP.F16.E4M3.UNPACK_B R14, R14.H1\nF2FP.F16.E4M3.UNPACK_B R17, R15.reuse\nF2FP.F16.E4M3.UNPACK_B R15, R15.H1\nF2FP.F16.E4M3.UNPACK_B R4, R10.reuse\nF2FP.F16.E4M3.UNPACK_B R8, R10.H1\